"use client";

// Research result widget: labels, intervals and per-algorithm AUCs; it makes no prediction and gives no signal.
// The table layout comes from the author's research view. This repository ships only ILLUSTRATIVE figures, randomly
// generated by terminal_demo.generate (see docs/RESEARCH.md); loadLocal rejects any file not marked as generated, and
// this widget says prominently that the numbers are not research results.

import { useQuery } from "@tanstack/react-query";
import { isNotIncluded, loadLocal, signed, type Research } from "../../lib/api";
import NotIncluded from "../NotIncluded";

const HORIZON: Record<string, string> = { illustrative_1d: "1-day (illustrative)", illustrative_5d: "5-day (illustrative)" };

export default function ResearchWidget() {
  const { data, error } = useQuery({ queryKey: ["research"], queryFn: () => loadLocal<Research>("research.json"), staleTime: Infinity });
  if (error)
    return isNotIncluded(error) ? <NotIncluded file={error.file} /> : (
      <div className="p-2 down" role="alert" data-testid="research-error">Research figures unavailable: {(error as Error).message}</div>
    );
  if (!data) return <div className="p-2 dim">Loading local data…</div>;
  if (data.illustrative !== true)
    return <div className="p-2 down" role="alert" data-testid="research-error">Research figures unavailable: the file is not marked illustrative.</div>;
  const first = Object.values(data.results)[0];

  return (
    <div className="p-2 flex flex-col gap-2 text-[11px]" data-testid="research">
      <div className="border border-[var(--amber)] px-2 py-1 text-[var(--amber)] font-bold tracking-wider" role="note" data-testid="illustrative-label">
        ILLUSTRATIVE FIGURES — RANDOMLY GENERATED, NOT RESEARCH RESULTS
      </div>
      <div className="dim">
        How the terminal presents a macro-versus-market evaluation: does adding a macro/risk block improve 1-day and 5-day
        direction discrimination over price/volume features? Every number below is a random draw from the demo generator
        {data.generator ? ` (${data.generator.name}, seed ${data.generator.seed})` : ""}; no model was fitted and nothing was
        evaluated. The author&apos;s private historical evaluation is not included in this repository.
      </div>
      <table className="data-table">
        <thead><tr><th>Horizon</th><th>Label</th><th>ΔAUC</th><th>{Math.round(first.ci_level * 1000) / 10}% interval</th></tr></thead>
        <tbody>
          {Object.entries(data.results).map(([t, r]) => (
            <tr key={t} data-testid={`result-${t}`}>
              <td>{HORIZON[t] ?? t}</td>
              <td className="amber">{r.label}</td>
              <td>{signed(r.estimate)}</td>
              <td>{signed(r.interval[0])} to {signed(r.interval[1])}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table className="data-table">
        <thead><tr><th>Horizon / algorithm</th><th>AUC mkt</th><th>AUC macro</th><th>ΔAUC</th></tr></thead>
        <tbody>
          {Object.entries(data.results).flatMap(([t, r]) =>
            Object.entries(r.per_algorithm).map(([m, a]) => (
              <tr key={t + m}>
                <td>{HORIZON[t] ?? t} · {m}</td>
                <td>{a.auc_market_only.toFixed(4)}</td>
                <td>{a.auc_macro_enhanced.toFixed(4)}</td>
                <td>{signed(a.delta_auc)}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
      <div className="dim" data-testid="illustrative-provenance">
        Figures: {data.policy_id} · {data.approval_status} · {data.multiplicity}. An interval that excludes zero means nothing here:
        the values are random. Nothing here is a trading signal.
      </div>
    </div>
  );
}
